s=s.replace("scene.quotes=result;scene.lines={};", "const old=scene.quotes;scene.quotes=result;for(const id of Object.keys(scene.lines)){if(!result.some(q=>q.symbol===id&&q.stamp.slice(0,8)===old.find(o=>o.symbol===id)?.stamp.slice(0,8)))delete scene.lines[id]}scene.alert=tracker.update(result.find(q=>q.symbol===(settings.focus||codes[0])),settings);");
