s=s.replace("const c=canvas.getContext('2d')!;c.fillStyle='#0b1018';c.fillRect(0,0,W,H);", "const c=canvas.getContext('2d')!;c.fillStyle='#0b1018';c.fillRect(0,0,W,H);let selection:string[]=[];try{selection=symbols(s.symbols??defaults.symbols)}catch{}const pages=Math.max(1,Math.ceil(selection.length/4));const cycle=pages+1;const active=s.mode==='rotate'?page%cycle:page;if(s.mode==='detail'||(s.mode==='rotate'&&active===pages)){drawDetail(canvas,scene,s,s.focus||selection[0]||'');return}page=active;");
