s=s.replace("catch{}const count=", "catch{}if(s.sort==='gain'||s.sort==='loss'){const sign=s.sort==='gain'?-1:1;codes.sort((a,b)=>{const x=scene.quotes.find(q=>q.symbol===a)?.percent,y=scene.quotes.find(q=>q.symbol===b)?.percent;return x===undefined?1:y===undefined?-1:sign*(x-y)})}const count=");
